'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let view='inverse',rsaKey=null,congruenceMode='solve';
const config={inverse:{title:'Inverse modulaire',text:'Entrez a et n pour trouver l’entier x tel que a × x ≡ 1 (mod n).'},euclide:{title:'Euclide & Bézout',text:'Calculez le PGCD, le PPCM et les coefficients de Bézout de deux entiers.'},euler:{title:'Indicatrice d’Euler',text:'Décomposez n en facteurs premiers pour calculer le nombre d’entiers premiers avec n.'},rsa:{title:'Chiffrement RSA',text:'Choisissez deux nombres premiers, construisez vos clés et chiffrez ou déchiffrez un message.'}};
config.ppcm={title:'PPCM',text:'Trouvez le plus petit multiple commun de deux entiers, à partir de leur PGCD.'};
config.congruences={title:'Congruences',text:'Calculez un reste, résolvez ax ≡ b (mod n), ou vérifiez une congruence.'};
config.fermat={title:'Fermat & Euler',text:'Calculez une puissance modulo n. Vérifiez les conditions avant de réduire son exposant.'};
const field=(id,title,hint,value)=>`<label for="${id}">${title}<small>${hint}</small><input id="${id}" name="${id}" inputmode="numeric" autocomplete="off" value="${value}" required></label>`;
const examples=items=>`<div class="examples">Essayer : ${items.map(([label,values])=>`<button type="button" data-example="${values}">${label}</button>`).join('')}</div>`;
const submit=label=>`<button class="primary" type="submit">${label}<span>→</span></button>`;
const step=(title,body)=>`<div class="step"><h3>${title}</h3>${body}</div>`;
const eq=s=>`<div class="equation">${s}</div>`;
const answer=(label,big,note,fail=false)=>`<div class="answer${fail?' fail':''}"><div class="answer-label"><span>${label}</span><span>${fail?'∅':'✓'}</span></div><div class="big">${big}</div><p>${note}</p></div>`;
function showError(err){$('#result').innerHTML=`<div class="error" role="alert">${esc(err.message)}</div>`;}
function mount(name){requestId++;view=config[name]?name:'home';const home=view==='home';$('#home-view').hidden=!home;$('#calculator-view').hidden=home;$('#home-link').classList.toggle('active',home);if(home)return;const c=config[view];$('#title').textContent=c.title;$('#crumb').textContent=c.title;$('#intro-text').textContent=c.text;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 let html='';if(view==='inverse')html=`<form id="calc"><div class="field-row">${field('a','Le nombre a','L’entier à inverser','17')}${field('n','Le module n','Un entier ≥ 2','43')}</div><p class="math-note">On cherche un entier x tel que<br><strong>a × x ≡ 1 (mod n).</strong></p>${submit('Trouver l’inverse')}${examples([['3 ; 7','3,7'],['17 ; 43','17,43'],['Sans inverse','2,6']])}</form>`;
 if(view==='euclide'||view==='ppcm')html=`<form id="calc"><div class="field-row">${field('a','Premier entier a','Positif, négatif ou nul','252')}${field('b','Second entier b','Positif, négatif ou nul','105')}</div><p class="math-note">Le dernier reste non nul est le PGCD. L’algorithme étendu donne les coefficients de Bézout.</p>${submit('Calculer & comprendre')}${examples([['252 ; 105','252,105'],['−17 ; 5','-17,5'],['35 ; 12','35,12']])}</form>`;
 if(view==='euler')html=`<form id="calc">${field('n','Le nombre n','De 1 à 1 000 000 000 000','72')}<p class="math-note">φ(n) compte les entiers de 1 à n premiers avec n.</p>${submit('Calculer φ(n)')}${examples([['φ(12)','12'],['φ(72)','72'],['φ(360)','360']])}</form>`;
 if(view==='congruences')html=`<form id="calc"><label for="congruence-mode">Que voulez-vous calculer ?<select id="congruence-mode"><option value="solve" ${congruenceMode==='solve'?'selected':''}>Résoudre ax ≡ b (mod n)</option><option value="remainder" ${congruenceMode==='remainder'?'selected':''}>Calculer le reste de a modulo n</option><option value="check" ${congruenceMode==='check'?'selected':''}>Vérifier a ≡ b (mod n)</option></select></label>${field('a',congruenceMode==='solve'?'Le coefficient a':'Le nombre a','Entier signé',congruenceMode==='solve'?'4':'38')}${congruenceMode==='remainder'?'':field('b',congruenceMode==='solve'?'Le second membre b':'Le nombre b','Entier signé',congruenceMode==='solve'?'5':'-5')}${field('n','Module n','Entier ≥ 2',congruenceMode==='solve'?'9':'43')}<p class="math-note">${congruenceMode==='solve'?'On cherche tous les entiers x qui vérifient ax ≡ b (mod n).':congruenceMode==='remainder'?'Le résultat est le reste compris entre 0 et n − 1.':'On vérifie si les deux nombres ont le même reste.'}</p>${submit(congruenceMode==='solve'?'Trouver les solutions':congruenceMode==='remainder'?'Calculer le reste':'Vérifier')}${examples(congruenceMode==='solve'?[['4x ≡ 5 (mod 9)','4,5,9'],['7x ≡ 2 (mod 11)','7,2,11'],['Plusieurs solutions','6,8,14'],['Sans solution','6,5,14']]:congruenceMode==='remainder'?[['38 mod 7','38,7'],['−5 mod 43','-5,43']]:[['38 ≡ −5','38,-5,43'],['Restes différents','17,4,7']])}</form>`;
 if(view==='fermat')html=`<form id="calc">${field('a','La base a','Entier signé','7')}${field('exponent','L’exposant k · facultatif','Vide : reste de a modulo n. Sinon, de 0 à 10¹².','222').replace(' required','')}${field('n','Le module n','De 2 à 1 000 000','13')}<p class="math-note">Fermat : n premier et PGCD(a, n) = 1. Euler : PGCD(a, n) = 1. Sinon, on utilise les carrés successifs sans réduire l’exposant.</p>${submit('Calculer le reste')}${examples([['Fermat','7,222,13'],['Euler','7,100,15'],['Non premiers entre eux','6,12,15']])}</form>`;
 if(view==='rsa')html=`<form id="calc"><div class="field-row">${field('p','Nombre premier p','Entre 2 et 1 000 000','61')}${field('q','Nombre premier q','Distinct de p','53')}</div>${field('e','Exposant public e','1 < e < φ(n), premier avec φ(n)','17')}${submit('Construire les clés')}${examples([['61 × 53','61,53,17'],['11 × 13','11,13,7']])}</form><h3 class="subhead">VOTRE MESSAGE</h3><label for="mode">Format du message<select id="mode"><option value="text">Texte (encodage UTF-8)</option><option value="number">Nombre entier</option></select></label><label for="message">Message ou blocs chiffrés<small>Pour déchiffrer : séparez les blocs par des espaces.</small><textarea id="message" spellcheck="false">Bonjour !</textarea></label><div class="rsa-buttons"><button class="primary" id="encrypt">Chiffrer →</button><button class="secondary" id="decrypt">Déchiffrer</button></div>`;
 $('#form-area').innerHTML=html;if(view==='congruences')$('#congruence-mode').onchange=()=>{congruenceMode=$('#congruence-mode').value;mount('congruences');};$('#calc').addEventListener('submit',ev=>{ev.preventDefault();calculate();});document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{const ids=view==='inverse'?['a','n']:(view==='euclide'||view==='ppcm')?['a','b']:view==='congruences'?(congruenceMode==='remainder'?['a','n']:['a','b','n']):view==='fermat'?['a','exponent','n']:view==='euler'?['n']:['p','q','e'];b.dataset.example.split(',').forEach((v,i)=>$('#'+ids[i]).value=v);if(view==='rsa'&&$('#p').value==='11'){$('#mode').value='number';$('#message').value='42';}calculate();});
 $('#calc').addEventListener('input',()=>{requestId++;$('#result').innerHTML='<p class="small-note">Les entrées ont changé. Lancez le calcul pour actualiser la démonstration.</p>';rsaKey=null;});if(view==='rsa'){$('#encrypt').onclick=()=>crypt('encrypt');$('#decrypt').onclick=()=>crypt('decrypt');$('#mode').onchange=()=>{requestId++;$('#message').value=$('#mode').value==='number'?'65':'Bonjour !';if(rsaKey)$('#result').innerHTML=rsaResult();};}
 $('#connection-title').textContent=view==='rsa'?'La clé privée est un inverse modulaire.':'L’inverse modulaire ouvre la porte à RSA.';$('#connection-text').textContent='Dans RSA, la clé privée d est l’inverse de e modulo φ(n). Ce que vous calculez ici est au cœur du déchiffrement.';$('#connection-link').innerHTML=view==='rsa'?'Revoir les inverses <span>→</span>':'Explorer RSA <span>→</span>';calculate();}

document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.view;});$('#connection-link').onclick=()=>{location.hash=view==='rsa'?'inverse':'rsa';};$('#print').onclick=()=>window.print();window.addEventListener('hashchange',()=>{mount(location.hash.slice(1));window.scrollTo(0,0);});mount(location.hash.slice(1));
